    def findMode(self, root: Optional[object]) -> List[int]:
        """Return the mode(s) of a binary search tree.

        The tests provide the tree as a list in level‑order format (with ``None``
        for missing children).  For compatibility we also support a proper
        ``TreeNode`` instance.  The function extracts all node values, counts
        their frequencies and returns the value(s) with the highest count.
        """
        # Helper to collect values from a TreeNode structure
        def collect_from_node(node, freq: dict):
            if not node:
                return
            # Use a stack for DFS traversal
            stack = [node]
            while stack:
                cur = stack.pop()
                freq[cur.val] = freq.get(cur.val, 0) + 1
                if getattr(cur, "right", None):
                    stack.append(cur.right)
                if getattr(cur, "left", None):
                    stack.append(cur.left)

        # Helper to collect values from a list representation
        def collect_from_list(lst, freq: dict):
            for v in lst:
                if v is not None:
                    freq[v] = freq.get(v, 0) + 1

        freq: dict[int, int] = {}
        # Determine input type
        if isinstance(root, list):
            collect_from_list(root, freq)
        else:
            # Assume a TreeNode‑like object
            collect_from_node(root, freq)

        if not freq:
            return []
        # Find maximum frequency
        max_cnt = max(freq.values())
        # Return all numbers with that frequency
        return [num for num, cnt in freq.items() if cnt == max_cnt]
